using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
public class QuotaAuditEvent {public DateTime Utc;public string Kind,Attempt,Windows,Method,Result,Model;public bool? RequestStarted;public long? InputTokens,CachedTokens,OutputTokens;}
public sealed class QuotaAudit {
 readonly string path;readonly object gate=new object();readonly JavaScriptSerializer json=new JavaScriptSerializer();public string Status="本地记录就绪";
 public QuotaAudit(string folder){path=Path.Combine(folder,"codex-quota-events.jsonl");}
 public bool Add(QuotaAuditEvent item){if(item==null)return false;lock(gate){try{Directory.CreateDirectory(Path.GetDirectoryName(path));using(var stream=new FileStream(path,FileMode.Append,FileAccess.Write,FileShare.Read))using(var writer=new StreamWriter(stream,new System.Text.UTF8Encoding(false))){writer.WriteLine(json.Serialize(item));writer.Flush();stream.Flush(true);}Status="本地记录已保存";return true;}catch(IOException){Status="额度记录无法写入";return false;}catch(UnauthorizedAccessException){Status="额度记录无法写入";return false;}}}
 public QuotaAuditEvent[] Recent(DateTime since){lock(gate){if(!File.Exists(path))return new QuotaAuditEvent[0];try{if(new FileInfo(path).Length>16777216){Status="记录超过16MB，请先备份";return new QuotaAuditEvent[0];}var result=new List<QuotaAuditEvent>();foreach(string line in File.ReadLines(path))try{var e=json.Deserialize<QuotaAuditEvent>(line);if(e!=null&&e.Utc>=since)result.Add(e);}catch(ArgumentException){}catch(InvalidOperationException){}return result.OrderByDescending(x=>x.Utc).Take(1000).ToArray();}catch(IOException){Status="额度记录无法读取";return new QuotaAuditEvent[0];}catch(UnauthorizedAccessException){Status="额度记录无法读取";return new QuotaAuditEvent[0];}}}
 public QuotaAuditEvent[] Between(DateTime start,DateTime end){return Recent(start.ToUniversalTime()).Where(e=>e.Utc<end.ToUniversalTime()).ToArray();}
 public static QuotaAuditEvent[] WithLegacy(QuotaAuditEvent[] events,IEnumerable<CodexQuotaReset> legacy,DateTime start,DateTime end){var list=new List<QuotaAuditEvent>(events??new QuotaAuditEvent[0]);foreach(var item in legacy??new CodexQuotaReset[0]){if(item==null||item.ObservedUtc<start.ToUniversalTime()||item.ObservedUtc>=end.ToUniversalTime())continue;string window=item.Minutes==300?"五小时":item.Minutes==10080?"周额度":"";if(window.Length==0||list.Any(e=>e.Kind=="reset-observed"&&e.Windows==window&&Math.Abs((e.Utc-item.ObservedUtc).TotalSeconds)<2))continue;list.Add(new QuotaAuditEvent{Utc=item.ObservedUtc,Kind="reset-observed",Windows=window,Method="旧版首次检测（触发来源未知）",Result="额度 "+item.PreviousRemaining.ToString("F1")+"% → "+item.Remaining.ToString("F1")+"%"});}return list.OrderBy(e=>e.Utc).ToArray();}
 public static string WindowNames(string reservation){var values=(reservation??"").Split('|').Select(k=>k.Split(':')).Where(p=>p.Length>=3).Select(p=>p[1]=="300"?"五小时":p[1]=="10080"?"周额度":"未知").Distinct().ToArray();return String.Join("、",values);}
 public static string Describe(QuotaAuditEvent e){string tokens=e.InputTokens.HasValue?"输入 "+e.InputTokens+"（缓存 "+(e.CachedTokens.HasValue?e.CachedTokens.ToString():"未知")+"），输出 "+(e.OutputTokens.HasValue?e.OutputTokens.ToString():"未知"):"token：未获得官方用量";return e.Utc.ToLocalTime().ToString("MM-dd HH:mm:ss")+" · "+e.Windows+" · "+e.Method+" · "+e.Result+(e.Kind=="wake-result"?" · "+(e.RequestStarted==true?"CLI 已启动，是否发出模型请求以结果为准":"未启动模型进程")+" · "+tokens:"");}
}
